import warnings

# Models that reject sampling settings on the routes you use.
# Fill this from your own probe requests, not from memory.
NO_SAMPLING = {'claude-opus-5', 'claude-sonnet-5'}
SAMPLING_KEYS = ('temperature', 'top_p', 'top_k')

def settings_for(model: str, shared: dict) -> dict:
    out = dict(shared)  # never mutate the shared object
    if model in NO_SAMPLING:
        dropped = [k for k in SAMPLING_KEYS if out.pop(k, None) is not None]
        if dropped:
            warnings.warn(f'{model}: dropped {dropped}')
    return out
